/* --------------------------------------------------------------- lookup utils */

const bySlug = new Map(minimaxH3Demos.map((demo) => [demo.slug, demo]));

export function getDemoBySlug(slug) {
  return bySlug.get(slug);
}

/** Throws in development if a slug is misspelled inside a component. */
export function requireDemo(slug) {
  const demo = bySlug.get(slug);
  if (!demo) throw new Error(`[minimaxH3Demos] unknown demo slug: ${slug}`);
  return demo;
}

export function getDemosBySlugs(slugs) {
  return slugs.map((slug) => requireDemo(slug));
}

export function getFeaturedDemos() {
  return minimaxH3Demos.filter((demo) => demo.featured);
}

export function getDemosByCategory(category) {
  if (!category || category === 'All') return minimaxH3Demos;
  return minimaxH3Demos.filter((demo) => demo.category === category);
}

/** Display order for the gallery filter bar. */
export const MINIMAX_CATEGORIES = [
  'All',
  "Action",
  "Animation",
  "Beauty",
  "Characters",
  "Cinema",
  "Commercial",
  "Fashion",
  "Food",
  "Social",
  "UGC",
  "VFX",
  "Web / UI",
];

/** Category -> count, used to label / hide empty filters. */
export function getCategoryCounts() {
  return minimaxH3Demos.reduce((acc, demo) => {
    acc[demo.category] = (acc[demo.category] || 0) + 1;
    return acc;
  }, {});
}

/* ------------------------------------------------------------------- ratios */

/**
 * Upstream ratios are not all clean 16:9 (e.g. "40:17", "92:39", "959:540").
 * Returns a numeric width/height ratio so frames can be sized without ever
 * distorting the source media.
 */
export function ratioToNumber(aspectRatio = undefined, fallback = 16 / 9) {
  if (!aspectRatio) return fallback;
  const [w, h] = aspectRatio.split(':').map(Number);
  if (!w || !h) return fallback;
  return w / h;
}

export function isVertical(demo) {
  return ratioToNumber(demo.aspectRatio) < 1;
}

export function formatDuration(demo) {
  return demo.duration ? `${demo.duration}s` : '—';
}

/* --------------------------------------------------------- prompt (lazy load) */

/**
 * Full prompt text lives in a separate chunk (~69KB across 30 demos) so the
 * landing page never ships it on first paint. The prompt modal awaits this.
 */
export async function loadDemoPrompt(slug) {
  const { minimaxH3Prompts } = await import('./minimaxH3Prompts');
  return minimaxH3Prompts[slug];
}

/* ------------------------------------------------- CTA routing (single layer) */

/**
 * The ONE place that maps a demo category to an in-app studio route.
 * Components must never hardcode studio URLs.
 *
 * Every value below is a real route key from src/lib/router.js pageLoaders.
 */
// 2026-08-17: remapped to real, prefill-able studios. `ai-vfx` is an iframe
// that cannot receive a prefill, so VFX/Web-UI demos now land in `effects`
// (which reads the staged prefill). Images-driven demos (Commercial/Beauty/
// Food) land in `commercial` for product shots but are also offered the video
// route from the gallery.
export const CATEGORY_ROUTES = {
  Commercial: 'commercial',
  UGC: 'influencer',
  Cinema: 'cinema',
  Action: 'cinema',
  Fashion: 'influencer',
  Animation: 'cinema',
  Characters: 'character',
  Food: 'influencer',
  Beauty: 'commercial',
  VFX: 'effects',
  Social: 'storyboard',
  'Web / UI': 'effects',
};

/** Fallback studio when a category has no explicit mapping. */
export const DEFAULT_CREATE_ROUTE = 'video';

/** Prefix for the template id handed to the destination studio. */
export const TEMPLATE_PREFIX = 'minimax-h3-';

/**
 * Resolves the "Create This Style" destination for a demo.
 *
 * Returns router-native values instead of a bare string because this app is a
 * hash-routed SPA: a real `/commercial` href would 404 on the server.
 */
export function getCreateTarget(demo) {
  const route = CATEGORY_ROUTES[demo.category] || DEFAULT_CREATE_ROUTE;
  const params = {
    template: `${TEMPLATE_PREFIX}${demo.slug}`,
    ref: 'minimax-h3',
  };
  const query = new URLSearchParams(params).toString();
  return { route, params, href: `/?${query}#/${route}` };
}

/** Convenience wrapper matching the requested helper name. */
export function getCreateUrl(demo) {
  return getCreateTarget(demo).href;
}

/* --------------------------------- prefill-aware target resolution (2026-08) */

export const MODEL_FOR_TARGET = {
  video: 'minimax-hailuo-2.3-standard-t2v',
  cinema: 'minimax-hailuo-2.3-standard-t2v',
  commercial: 'ai-product-shot',
  influencer: 'minimax-hailuo-2.3-standard-t2v',
  character: 'minimax-hailuo-2.3-standard-t2v',
  effects: 'minimax-hailuo-2.3-standard-t2v',
  storyboard: 'minimax-hailuo-2.3-standard-t2v',
  image: 'minimax-image-01',
  audio: 'minimax-music',
};

/**
 * Returns every demo annotated with the studio route + model it should open in
 * ("Create This Style"). Centralises the category→studio decision so the
 * landing sections, the in-studio examples rail, and the prompt modal all
 * agree on where a demo goes.
 */
export function getMiniMaxDemosWithTargets() {
  return minimaxH3Demos.map((d) => {
    const route = CATEGORY_ROUTES[d.category] || DEFAULT_CREATE_ROUTE;
    return { ...d, __route: route, __model: MODEL_FOR_TARGET[route] || MODEL_FOR_TARGET.video };
  });
}

/** Direct, prefill-aware "open this demo in its studio" action. */
export function openDemoInStudio(demo) {
  // Lazy import avoids a circular dep with examplesRail/studioPrefill.
  return import('../lib/studioPrefill.js').then(({ stageStudioPrefill }) =>
    import('../lib/router.js').then(({ navigate }) => {
      const route = demo.__route || CATEGORY_ROUTES[demo.category] || DEFAULT_CREATE_ROUTE;
      const model = demo.__model || MODEL_FOR_TARGET[route] || MODEL_FOR_TARGET.video;
      // aspect ratio -> one Hailuo supports
      const [w, h] = (demo.aspectRatio || '16:9').split(':').map(Number);
      const ratio = !w || !h ? '16:9' : w < h ? '9:16' : '16:9';
      stageStudioPrefill({
        route,
        prompt: '', // filled by the consumer from loadDemoPrompt
        model,
        params: { aspect_ratio: ratio, _sourceSlug: demo.slug, _sourceTitle: demo.title },
        ref: 'minimax-h3',
      });
      navigate(route);
    })
  );
}
